BULLES_LOAD({"ep":"ep17","part":"pages","pages":[{"id":"E17P00","w":1200,"h":321,"img":"data:image/webp;base64,","items":{"fr":[{"b":[0.175,0.243,0.56,0.7009],"t":"Épisode 17 : Un Nouveau Départ","s":"Titre"},{"b":[0.4725,0.2804,0.35,0.4766]}],"en":[{"b":[0.175,0.243,0.48,0.7009],"t":"Episode 17: A Fresh Start","s":"Title"},{"b":[0.4725,0.2804,0.35,0.4766]}],"pt":[{"b":[0.175,0.243,0.5375,0.7009],"t":"Episódio 17: Um Novo Começo"},{"b":[0.4725,0.2804,0.35,0.4766]}],"es":[{"b":[0.1425,0.3364,0.7175,0.6075],"t":"Episodio 17: Un nuevo comienzo","s":"Título"}],"de":[{"b":[0.175,0.243,0.4825,0.7009],"t":"Episode 17: Ein Neuanfang","s":"Titel"},{"b":[0.4725,0.2804,0.35,0.4766]}],"it":[{"b":[0.175,0.243,0.5,0.7009],"t":"Episodio 17: Un nuovo inizio"},{"b":[0.4725,0.2804,0.35,0.4766]}]}},{"id":"E17P01","w":1200,"h":1694,"img":"data:image/webp;base64,","items":{"fr":[{"b":[0.35,0.4941,0.22,0.1045],"t":"NON ! JE PARS !!","s":"Pepper"},{"b":[0.1775,0.6074,0.165,0.0939],"t":"Mais Pepper... ...Reviens...","s":"Cumin"},{"b":[0.71,0.6393,0.28,0.1027],"t":"Vous n'enseignez pas de vraie sorcellerie ! Je m'en vais !... chez les sorcières de Ah !","s":"Pepper"},{"b":[0.315,0.9156,0.12,0.0496],"t":"Zo oo sh !","s":"Son"}],"en":[{"b":[0.3475,0.4959,0.2225,0.1027],"t":"NO! I'M LEAVING!!","s":"Pepper"},{"b":[0.1775,0.6074,0.165,0.0939],"t":"But Pepper... Come back...","s":"Cumin"},{"b":[0.71,0.6393,0.28,0.1027],"t":"You don't teach real witchcraft! I'm going - to the witches of Ah!","s":"Pepper"},{"b":[0.3175,0.9174,0.11,0.0478],"t":"Wo oo sh !","s":"Sound"}],"pt":[{"b":[0.3475,0.4959,0.2225,0.1027],"t":"NÃO! EU VOU EMBORA!!"},{"b":[0.1775,0.6074,0.165,0.0939],"t":"Mas Pepper... Volte..."},{"b":[0.71,0.6393,0.28,0.1027],"t":"Vocês não ensinam feitiçaria de verdade! Eu vou sim - para as bruxas de Ah!"},{"b":[0.3175,0.9156,0.12,0.0496],"t":"Wo oo sh !"}],"es":[{"b":[0.35,0.4941,0.22,0.1045],"t":"¡ O! ¡¡ME VOY!!"},{"b":[0.1775,0.6074,0.165,0.0939],"t":"Pero Pimienta... ...Vuelve...","s":"Cumino"},{"b":[0.71,0.634,0.285,0.1027],"t":"¡Con vosotras no aprendo auténtica hechicería! ¡Voy a ir a ver a las brujas de Ah!","s":"Pimienta"},{"b":[0.3275,0.9085,0.12,0.0514],"t":"¡Zo oo sh !","s":"Sonido"}],"de":[{"b":[0.3475,0.4959,0.2225,0.1027],"t":"NEIN! ICH GEHE!!!","s":"Pepper"},{"b":[0.1775,0.6074,0.165,0.0939],"t":"Aber Pepper... bleib hier...","s":"Kümmel"},{"b":[0.71,0.6393,0.28,0.1027],"t":"Ihr unterrichtet keine echte Zauberei! Ich gehe - zu den Hexen von Ah!","s":"Pepper"},{"b":[0.3175,0.9156,0.1175,0.0496],"t":"Wuu u s !"}],"it":[{"b":[0.3475,0.4959,0.2225,0.1027],"t":"NO! ME NE VADO!!"},{"b":[0.1775,0.6074,0.1675,0.0992],"t":"Ma Pepper... Torna indietro..."},{"b":[0.71,0.6393,0.28,0.1027],"t":"Non mi insegnate la vera stregoneria! Vado dalle streghe di Ah!"},{"b":[0.315,0.9156,0.125,0.0496],"t":"Swo oo sh !"}]}},{"id":"E17P02","w":1200,"h":1694,"img":"data:image/webp;base64,","items":{"fr":[{"b":[0.04,0.2692,0.4025,0.1417],"t":"Bon, rejoignons le pays des Lunes couchantes. Shichimi nous conseillera pour entrer chez les sorcières de Ah.","s":"Pepper"},{"b":[0.635,0.4055,0.32,0.1169],"t":"Carrot, sors la carte et la boussole : il y a trop de nuages et je ne sais pas où je vais.","s":"Pepper"},{"b":[0.655,0.5242,0.335,0.1204],"t":"BrrOoooOoo ! !","s":"Son"},{"b":[0.1775,0.7509,0.0375,0.0248],"t":"N","s":"Écriture"},{"b":[0.35,0.7828,0.23,0.1293],"t":"ZUT ! Des turbulences ! ACCROCHE-TOI !","s":"Pepper"},{"b":[0.6575,0.8076,0.1725,0.0885],"t":"Oh non !!!","s":"Pepper"}],"en":[{"b":[0.04,0.2692,0.4025,0.1328],"t":"Alright then, off to the land of the setting moons Shichimi can tell us how to join the witches of Ah","s":"Pepper"},{"b":[0.635,0.4073,0.3175,0.1027],"t":"Carrot, get out the map and compass: it's too cloudy to see where I'm going","s":"Pepper"},{"b":[0.66,0.5401,0.3025,0.1098],"t":"BrrOoooOoo! !","s":"Sound"},{"b":[0.1775,0.7509,0.0375,0.0248],"t":"N","s":"Writing"},{"b":[0.3525,0.7828,0.2075,0.1328],"t":"DRATS! Turbulence! HOLD ON!","s":"Pepper"},{"b":[0.6575,0.8076,0.1725,0.0885],"t":"Oh no!!!","s":"Pepper"}],"pt":[{"b":[0.04,0.2692,0.4025,0.1328],"t":"Certo então, vamos para a terra em que as luas se põe Shichimi pode nos dizer como chegar até as bruxas de Ah"},{"b":[0.635,0.4073,0.3175,0.1027],"t":"Carrot, pegue o mapa e a bússola: está muito nublado e não enxergo nada"},{"b":[0.655,0.5277,0.3225,0.1169],"t":"BrrOoooOoo! !"},{"b":[0.1775,0.7509,0.0375,0.0248],"t":"N"},{"b":[0.3525,0.7828,0.2075,0.1328],"t":"CACA! SEGURA AÍ! Turbulência!"},{"b":[0.6575,0.8076,0.1725,0.0885],"t":"Oh não!!!"}],"es":[{"b":[0.04,0.2692,0.4025,0.1452],"t":"Veamos, tenemos que ir al país de las puestas de luna. Shichimi nos dirá como podemos entrar en las brujas de Ah.","s":"Pimienta"},{"b":[0.635,0.4055,0.315,0.1169],"t":"Zanahoria, saca el mapa y la brújula: hay demasiadas nubes y no sé hacia dónde vamos.","s":"Pimienta"},{"b":[0.6525,0.5207,0.3475,0.1328],"t":"¡ !"},{"b":[0.1775,0.7509,0.0375,0.0248],"t":"N","s":"Escritura"},{"b":[0.35,0.7828,0.23,0.1293],"t":"¡Turbulencias! ¡AGÁRRATE BIEN! ¡","s":"Pimienta"},{"b":[0.6575,0.8076,0.1725,0.0885],"t":"¡¡¡Oh, no!!!","s":"Pimienta"}],"de":[{"b":[0.04,0.2692,0.4025,0.1346],"t":"Also gut, auf geht's in das Land der untergehenden Monde Shichimi kann uns sagen, wie wir zu den Hexen von Ah kommen","s":"Pepper"},{"b":[0.635,0.4073,0.3175,0.1027],"t":"Carrot, gib mir Kompass und Karte: bei dem Nebel sehe ich nicht, wo es hingeht.","s":"Pepper"},{"b":[0.6525,0.526,0.3375,0.1204],"t":"BrrUuuuMmm! !","s":"Geräusch"},{"b":[0.1775,0.7509,0.0375,0.0248],"t":"N","s":"Schrift"},{"b":[0.3525,0.7828,0.2075,0.1328],"t":"MIST! Ein Sturm! FESTHALTEN!","s":"Pepper"},{"b":[0.6575,0.8076,0.1725,0.0885],"t":"Oh nein!!!","s":"Pepper"}],"it":[{"b":[0.04,0.2692,0.4025,0.1328],"t":"Bene, andiamo nel paese delle Lune Calanti Shichimi ci dirà come incontrare le streghe di Ah"},{"b":[0.635,0.4073,0.325,0.108],"t":"Carrot, prendi mappa e bussola: ci sono troppe nuovole per seguire la strada"},{"b":[0.655,0.5207,0.345,0.124],"t":"BrrOoooMmm! !"},{"b":[0.1775,0.7509,0.0375,0.0248],"t":"N"},{"b":[0.3525,0.7828,0.2075,0.1328],"t":"AARGG! TIENITI FORTE! Turbolenze!"},{"b":[0.6575,0.8076,0.1725,0.0885],"t":"Oh no !!!"}]}},{"id":"E17P03","w":1200,"h":1694,"img":"data:image/webp;base64,","items":{"fr":[{"b":[0.7825,0.1116,0.1325,0.0779],"t":"CrrAsh ! rAsh !"}],"en":[{"b":[0.7825,0.1133,0.125,0.0762],"t":"CrrAsh! rAsh !"}],"pt":[{"b":[0.7825,0.1151,0.12,0.0744],"t":"CrrAsh! rAsh !"}],"es":[{"b":[0.78,0.1063,0.15,0.0903],"t":"¡ rAsh !"}],"de":[{"b":[0.78,0.1098,0.1375,0.0815],"t":"Krawumm! !","s":"Geräusch"}],"it":[{"b":[0.7825,0.1151,0.12,0.0744],"t":"CrrAsh! rAsh !"}]}},{"id":"E17P04","w":1200,"h":1694,"img":"data:image/webp;base64,","items":{"fr":[{"b":[0.095,0.0319,0.1625,0.1222],"t":"Ne t'inquiète surtout pas, Carrot...","s":"Pepper"},{"b":[0.1625,0.2798,0.335,0.1169],"t":"\"Un bon regard noir évite bien des sorts inutiles !... ...Mate-les. Domine-les !\"","s":"Cayenne"},{"b":[0.235,0.5844,0.3825,0.1505],"t":"Moi, j'aurais bien sûr préféré apprendre quelques bons sorts d'attaque ; mais bon...","s":"Pepper"},{"b":[0.1925,0.7651,0.0725,0.0549]},{"b":[0.75,0.7704,0.2075,0.1434],"t":"Zut... plus de balai ni d'affaires. La route va être longue...","s":"Pepper"}],"en":[{"b":[0.095,0.0319,0.1625,0.1222],"t":"Above all, don't panic, Carrot...","s":"Pepper"},{"b":[0.1625,0.2798,0.335,0.1169],"t":"\"A good dark stare is worth a dozen useless curses! ... ...Stare them down. Dominate them! \"","s":"Cayenne"},{"b":[0.245,0.5862,0.3725,0.1488],"t":"Personally, I would've preferred to learn a few good attack spells; but anyway...","s":"Pepper"},{"b":[0.19,0.7686,0.0675,0.0531]},{"b":[0.7475,0.7686,0.2125,0.147],"t":"shoot... no more broom or equipment, this is going to be a long trip...","s":"Pepper"}],"pt":[{"b":[0.095,0.0319,0.1625,0.1222],"t":"Acima de tudo, não entre em pânico, Carrot..."},{"b":[0.1625,0.2798,0.335,0.1169],"t":"\"Uma encarada profunda vale dezenas de maldições inúteis! ... ...Encare-os. Domine-os! \""},{"b":[0.245,0.5862,0.3725,0.1488],"t":"Pessoalmente, eu preferiria aprender feitiços de ataque; mas tanto faz..."},{"b":[0.19,0.7686,0.0675,0.0531]},{"b":[0.7475,0.7686,0.2125,0.147],"t":"Porcaria... Sem vassoura e equipamentos, esta vai ser uma longa viagem..."}],"es":[{"b":[0.0925,0.0372,0.17,0.1169],"t":"Sobre todo no muestres miedo, Zanahoria...","s":"Pimienta"},{"b":[0.1475,0.2798,0.35,0.1169],"t":"\"Una mirada fija, penetrante y sombría puede evitar hechizos inútiles... ...¡Rebájalos! ¡Domínalos!\"","s":"Cayena"},{"b":[0.235,0.5844,0.3825,0.1505],"t":"Yo habría preferido aprender algunos buenos hechizos de ataque; pero bueno...","s":"Pimienta"},{"b":[0.1925,0.7615,0.0775,0.062]},{"b":[0.74,0.7704,0.2175,0.1434],"t":"Buf... ya no tengo escoba ni nada. Va a ser un viaje largo...","s":"Pimienta"}],"de":[{"b":[0.0825,0.0319,0.19,0.1222],"t":"Wir müssen jetzt ganz ruhig bleiben, Carrot...","s":"Pepper"},{"b":[0.16,0.2798,0.3375,0.1169],"t":"\"Ein böser Blick ist besser als ein dutzend schwacher Zaubersprüche! ... ...starre sie nieder. Kontrolliere sie!\"","s":"Cayenne"},{"b":[0.2425,0.5862,0.375,0.1488],"t":"Ich hätte lieber ein paar Angriffszauber gelernt... aber was soll's...","s":"Pepper"},{"b":[0.19,0.7686,0.0675,0.0531]},{"b":[0.7475,0.7686,0.2125,0.147],"t":"Ohh je... Kein Besen, keine Ausrüstung, das wird ein langer Weg...","s":"Pepper"}],"it":[{"b":[0.095,0.0319,0.1625,0.1222],"t":"Innanzitutto, niente panico, Carrot..."},{"b":[0.1575,0.2798,0.34,0.1169],"t":"\"Un'occhiataccia come si deve è meglio di molti inutili incantesimi! ... ...Guardalo fisso. Controllalo! \""},{"b":[0.245,0.5862,0.3725,0.1488],"t":"Personalmente, avrei preferito imparare qualche buona mossa d'attacco; comunque..."},{"b":[0.19,0.7668,0.0725,0.0549]},{"b":[0.7475,0.7686,0.2025,0.147],"t":"gasp... niente più scopa né zaino, sarà un lungo viaggio..."}]}},{"id":"E17P05","w":1200,"h":1694,"img":"data:image/webp;base64,","items":{"fr":[{"b":[0.635,0.2568,0.3325,0.1328],"t":"\"Connaître les plantes comestibles ? C'est connaître des potions toutes prêtes contre la faim.\"","s":"Cumin"},{"b":[0.155,0.5189,0.1075,0.0496],"t":"Groo","s":"Carrot"},{"b":[0.28,0.4516,0.2275,0.17],"t":"Moi aussi je suis à bout de forces... Et ça fait des jours qu'on n'a rien mangé.","s":"Pepper"},{"b":[0.18,0.6623,0.3025,0.147],"t":"M'en a-t-elle appris ne serait-ce qu'une seule ? Mais de vraies vraies potions ?...","s":"Pepper"}],"en":[{"b":[0.635,0.2568,0.335,0.1328],"t":"\"To know the edible plants is to know where to find ready-made potions against hunger!\"","s":"Cumin"},{"b":[0.155,0.5189,0.1075,0.0496],"t":"Groo","s":"Carrot"},{"b":[0.2875,0.4516,0.22,0.17],"t":"I'm totally worn out too Carrot... And it's been days since we've eaten anything.","s":"Pepper"},{"b":[0.19,0.673,0.285,0.1364],"t":"If only she had taught me a single one! But real real potions?...","s":"Pepper"}],"pt":[{"b":[0.635,0.2568,0.335,0.1328],"t":"\"Saber quais plantas são comestíveis é saber onde encontrar poções naturais contra a fome!\""},{"b":[0.155,0.5189,0.1075,0.0496],"t":"Groo"},{"b":[0.2875,0.4516,0.22,0.17],"t":"E já faz dias desde que comemos alguma coisa Eu também estou muito cansada, Carrot..."},{"b":[0.19,0.673,0.285,0.1364],"t":"Mas poções reais Se apenas ela tivesse me ensinado uma! uma"}],"es":[{"b":[0.635,0.2568,0.3275,0.1328],"t":"\"Conocer las plantas comestibles es conocer pociones ya preparadas contra el hambre.\"","s":"Cumino"},{"b":[0.155,0.5189,0.1075,0.0496],"t":"Groo","s":"Zanahoria"},{"b":[0.28,0.4516,0.2275,0.17],"t":"Yo también estoy a punto de desmayarme... Y ya hace días que no hemos comido nada.","s":"Pimienta"},{"b":[0.18,0.6623,0.3025,0.147],"t":"Si al menos me hubiera enseñado una sola... ¿Pero verdaderas verdaderas pociones?...","s":"Pimienta"}],"de":[{"b":[0.635,0.2568,0.335,0.1328],"t":"\"Zu wissen, welche Pflanzen essbar sind, ist wie ein fertiger Zaubertrank gegen Hunger!\"","s":"Kümmel"},{"b":[0.155,0.5189,0.1125,0.0496],"t":"Knurr","s":"Carrot"},{"b":[0.2875,0.4516,0.22,0.17],"t":"Ich bin auch total ausgehungert, Carrot... Seit Tagen haben wir nichts mehr gegessen.","s":"Pepper"},{"b":[0.175,0.673,0.3,0.1364],"t":"Wenn sie mir nur EINEN beigebracht hätte! Aber echte echte Zaubertränke?...","s":"Pepper"}],"it":[{"b":[0.635,0.255,0.335,0.1346],"t":"\"Conoscere le piante commestibili è come conoscere le pozioni belle pronte contro la fame!\""},{"b":[0.155,0.5189,0.1075,0.0496],"t":"Grup"},{"b":[0.2875,0.4516,0.22,0.17],"t":"Anch'io sono sfinita Carrot... E sono giorni che non mangiamo."},{"b":[0.19,0.673,0.285,0.1364],"t":"Ma vere pozioni?... Se solo me ne avessero insegnata una!"}]}},{"id":"E17P06","w":1200,"h":1694,"img":"data:image/webp;base64,","items":{"fr":[{"b":[0.405,0.3719,0.35,0.1169],"t":"\"Une vraie sorcière de Chaosah n'a besoin ni de cartes ni de boussole sous un ciel étoilé.\"","s":"Thym"},{"b":[0.7175,0.4374,0.2325,0.0992],"t":"... moi j'aurais préféré un vrai cours vrai de divination !"},{"b":[0.1175,0.6694,0.2575,0.0868],"t":"Courage Carrot ! Regarde, on y est !","s":"Pepper"}],"en":[{"b":[0.405,0.3719,0.31,0.1169],"t":"\"A true witch of Chaosah needs neither compass nor map. A starry sky will suffice\"","s":"Thyme"},{"b":[0.7075,0.4445,0.245,0.0921],"t":"... I would've preferred a real course in real divination!"},{"b":[0.0775,0.6659,0.2825,0.0903],"t":"Cheer up Carrot ! Look, we've arrived!","s":"Pepper"}],"pt":[{"b":[0.405,0.3719,0.31,0.1169],"t":"\"Uma verdadeira bruxa de Chaosah não precisa de bússola nem mapa. Basta um céu estrelado.\""},{"b":[0.7075,0.4445,0.245,0.0921],"t":"... Eu teria preferido um curso em adivinhação!"},{"b":[0.0775,0.6659,0.2825,0.0903],"t":"Anime-se Carrot ! Olha, nós chegamos!"}],"es":[{"b":[0.405,0.3719,0.35,0.1169],"t":"\"Una verdadera bruja de Chaosah no necesita ni mapas ni brújula. Le basta con un cielo estrellado.\"","s":"Tomillo"},{"b":[0.7175,0.4374,0.2325,0.0992],"t":"... ¡yo habría preferido un verdadero verdadero curso de adivinación!"},{"b":[0.1175,0.6694,0.2575,0.0868],"t":"¡Ánimo, Zanahoria! ¡Mira, hemos llegado!","s":"Pimienta"}],"de":[{"b":[0.405,0.3719,0.3275,0.1169],"t":"\"Eine echte Hexe von Chaosāh braucht weder Karte noch Kompass. Eine sternenklare Nacht genügt!\"","s":"Thymian"},{"b":[0.7075,0.4445,0.245,0.0921],"t":"... Ich hätte einen echten echten Kurs in Wahrsagerei bevorzugt!"},{"b":[0.0875,0.6712,0.2725,0.085],"t":"Komm Carrot! Schau, wir sind da!","s":"Pepper"}],"it":[{"b":[0.405,0.3719,0.31,0.1169],"t":"\"A una vera streaga di Chaosah non servono bussola e mappe. Basta un cielo stellato\""},{"b":[0.7075,0.4445,0.245,0.0921],"t":"... Avrei preferito un vero divinazione!"},{"b":[0.0775,0.6659,0.2825,0.0903],"t":"Coraggio Carrot ! Guarda, siamo arrivati!"}]}},{"id":"E17P07","w":1200,"h":1694,"img":"data:image/webp;base64,","items":{"fr":[{"b":[0.17,0.0319,0.315,0.1098],"t":"...et voilà. Tu connais à présent toute l'histoire.","s":"Pepper"},{"b":[0.4275,0.108,0.275,0.0832],"t":"... et tu me dis que tu es ici car elles ne t'ont rien"},{"b":[0.1025,0.9085,0.7975,0.0691]}],"en":[{"b":[0.1625,0.0266,0.3,0.1151],"t":"...so there you are. Now you know the whole story.","s":"Pepper"},{"b":[0.375,0.1063,0.3275,0.085],"t":"...and you tell me that you're here because they haven't taught you anything? anything g"},{"b":[0.095,0.9085,0.8125,0.0691]}],"pt":[{"b":[0.1625,0.0266,0.3,0.1151],"t":"...então é isso. Agora você sabe toda a história"},{"b":[0.375,0.1063,0.3275,0.085],"t":"...então você quer dizer que você está aqui porque elas não te ensinaram nada? nada"},{"b":[0.105,0.9085,0.7925,0.0691]}],"es":[{"b":[0.14,0.0283,0.345,0.1133],"t":"...y aquí estamos. Ahora conoces toda la historia.","s":"Pimienta"},{"b":[0.4275,0.108,0.275,0.0832],"t":"...¿y dices que estás aquí porque ellas no te han enseñado nada? enseñado nada"},{"b":[0.0775,0.9085,0.8475,0.0691]}],"de":[{"b":[0.1625,0.0266,0.3,0.1151],"t":"...und hier sind wir. Jetzt kennst du die ganze Geschichte.","s":"Pepper"},{"b":[0.375,0.1063,0.3275,0.085],"t":"...und du sagst mir, dass du hier bist, weil sie dir nichts"},{"b":[0.0875,0.9085,0.8275,0.0691]}],"it":[{"b":[0.1625,0.0266,0.3,0.1151],"t":"...così eccoci qua. Adesso sai tutta la storia."},{"b":[0.375,0.1063,0.3275,0.085],"t":"...e tu mi dici che sei qui perché non ti hanno insegnato niente? niente"},{"b":[0.0925,0.9085,0.82,0.0691]}]}},{"id":"E17P08","w":1200,"h":2178,"img":"data:image/webp;base64,","items":{"fr":[{"b":[0.3025,0.0441,0.3925,0.0413],"t":"Pepper&Carrot est entièrement libre, open-source, et sponsorisé grâce au mécénat de ses lecteurs. Pour cet épisode, merci aux 719 Mécènes :","s":"Crédits"},{"b":[0.195,0.9421,0.6125,0.0193],"t":"Vous aussi, devenez mécène de Pepper&Carrot sur www.patreon.com/davidrevoy","s":"Crédits"}],"en":[{"b":[0.295,0.0441,0.41,0.0413],"t":"Pepper&Carrot is entirely free(libre), open-source and sponsored thanks to the patronage of its readers. For this episode, thanks go to 719 Patrons:","s":"Credits"},{"b":[0.1925,0.9421,0.615,0.0207],"t":"You too can become a patron of Pepper&Carrot at www.patreon.com/davidrevoy","s":"Credits"}],"pt":[{"b":[0.2775,0.0441,0.4425,0.0413],"t":"Pepper&Carrot é totalmente grátis, com código aberto e patrocinada graças à gentil contribuição dos seus leitores. Para este episódio, obrigado aos seguintes 719 Patronos:"},{"b":[0.145,0.9421,0.71,0.0193],"t":"Você também pode se tornar um patrono de Pepper&Carrot em www.patreon.com/davidrevoy"}],"es":[{"b":[0.26,0.0427,0.4725,0.0427],"t":"Pepper&Carrot es completamente gratuito, de código abierto, y financiado gracias al mecenazgo de sus lectores. Para este episodio, gracias a 719 mecenas:","s":"Créditos"},{"b":[0.185,0.9408,0.63,0.022],"t":"Tú también puedes ser mecenas de Pepper&Carrot en www.patreon.com/davidrevoy","s":"Créditos"}],"de":[{"b":[0.295,0.0427,0.4125,0.0427],"t":"Pepper&Carrot ist komplett frei, Open Source und wird durch die Leser unterstützt und finanziert. Für diese Episode geht der Dank an die 719 Förderer:","s":"Impressum"},{"b":[0.215,0.9421,0.57,0.0207],"t":"Auch Du kannst Pepper&Carrot unterstützen: www.patreon.com/davidrevoy","s":"Impressum"}],"it":[{"b":[0.2875,0.0427,0.425,0.0427],"t":"Pepper&Carrot è completamente gratuito, open-source e sostenuto grazie alle gentili donazioni dei lettori. Per questo episodio, grazie ai 719 donatori :"},{"b":[0.1375,0.9421,0.725,0.0207],"t":"Anche tu puoi contribuire al prossimo episodio di Pepper&Carrot su www.patreon.com/davidrevoy"}]}}]});
